WITH base AS (SELECT *, INITCAP(TRIM(status)) AS status_title FROM payments WHERE paid_at >= TO_TIMESTAMP('2024-03-02 07:00:00') AND order_id IS NOT NULL AND method IN ('card', 'cash', 'bank_transfer')) SELECT DATE_TRUNC('QUARTER', paid_at) AS quarter_start, method, order_id, MIN(amount) AS min_amount, SIZE(COLLECT_SET(method)) AS num_methods, MIN(paid_at) AS first_paid_at, ROUND(AVG(amount), 2) AS avg_amount FROM base GROUP BY DATE_TRUNC('QUARTER', paid_at), method, order_id HAVING SIZE(COLLECT_SET(method)) >= 1 ORDER BY min_amount DESC NULLS LAST;
